import{_ as t,o as r,c as o,a3 as a}from"./chunks/framework.BveOjhN0.js";const p=JSON.parse('{"title":"Purchase Orders — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Purchase Orders — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/purchase-orders"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Purchase Orders — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/purchase-orders"}]]},"headers":[],"relativePath":"user-guide/purchase-orders.md","filePath":"user-guide/purchase-orders.md","lastUpdated":1785579980000}'),s={name:"user-guide/purchase-orders.md"};function n(i,e,d,c,l,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="purchase-orders-—-user-guide" tabindex="-1">Purchase Orders — User Guide <a class="header-anchor" href="#purchase-orders-—-user-guide" aria-label="Permalink to &quot;Purchase Orders — User Guide&quot;">​</a></h1><h2 id="who-can-use-purchase-orders" tabindex="-1">Who can use Purchase Orders <a class="header-anchor" href="#who-can-use-purchase-orders" aria-label="Permalink to &quot;Who can use Purchase Orders&quot;">​</a></h2><p>Your workspace must have <strong>Vendors</strong> installed first, then the <strong>Purchase Orders</strong> module (both free from Marketplace). Marketplace blocks installing Purchase Orders until Vendors is entitled. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>send</code>, <code>receive</code>, <code>cancel</code> as needed).</p><p>Without <strong>assign</strong>, you only see purchase orders assigned to you.</p><h2 id="list-table" tabindex="-1">List &amp; table <a class="header-anchor" href="#list-table" aria-label="Permalink to &quot;List &amp; table&quot;">​</a></h2><p>Open <strong>Purchase Orders</strong> from the sidebar, under the <strong>Purchasing</strong> group (next to Vendors). Search by title or number, filter by status or assignee, toggle <strong>My Purchase Orders</strong>, and switch KPI cards (Total, Mine, Draft, Sent, Partially received, Received) to quick-filter the table. The table shows the vendor and the <strong>latest note</strong>.</p><ul><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted purchase order from the row menu</li><li><strong>Delete permanently</strong> requires <code>purchase-orders.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-a-purchase-order" tabindex="-1">Create a purchase order <a class="header-anchor" href="#create-a-purchase-order" aria-label="Permalink to &quot;Create a purchase order&quot;">​</a></h2><ol><li>Click <strong>New purchase order</strong></li><li>Enter a title and select a <strong>Vendor</strong> (required)</li><li>Optionally set currency, order date, expected date, and notes</li><li>Add line items (description, quantity, unit price, tax rate) — subtotal, tax, and total are calculated automatically</li><li>Optionally set an assignee (requires <strong>assign</strong>)</li><li>Save</li></ol><p>Edit from the row menu or the detail sheet while the purchase order is still <strong>Draft</strong>. Editing replaces the full line-item list. After <strong>Send</strong>, content is locked; use status actions and assignment instead.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>A purchase order starts in <strong>Draft</strong>. Move it forward with:</p><ul><li><strong>Send</strong> (<code>draft → sent</code>) — marks the order as sent to the vendor (does not email the vendor or attach a PDF yet)</li><li><strong>Mark partially received</strong> (<code>sent → partially_received</code>) — acknowledges some of the order has arrived</li><li><strong>Mark received</strong> (<code>sent → received</code> or <code>partially_received → received</code>) — acknowledges the full order has arrived</li><li><strong>Cancel</strong> (<code>draft → cancelled</code>, <code>sent → cancelled</code>, or <code>partially_received → cancelled</code>)</li></ul><p>Invalid transitions (e.g. receiving directly from Draft) are rejected with a validation error. <code>Received</code> and <code>Cancelled</code> are terminal — no further transitions.</p><p>Receiving is an <strong>acknowledgement only</strong> — it does not post stock movements anywhere. There is no Inventory module on this platform yet.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the detail sheet or the create/edit form. The assignee receives an in-app notification when someone else assigns them.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the purchase order</li><li><strong>Activity</strong> — timeline of create, update, assignment, status change, note, and delete/restore events</li></ul><h2 id="convert-to-expense" tabindex="-1">Convert to expense <a class="header-anchor" href="#convert-to-expense" aria-label="Permalink to &quot;Convert to expense&quot;">​</a></h2><p>If the <strong>Expenses</strong> module is installed on your workspace and you have the <code>purchase-orders.convert</code> permission, a <strong>Convert to expense</strong> button appears on <strong>Sent</strong>, <strong>Partially received</strong>, and <strong>Received</strong> purchase orders (not on Draft or Cancelled). Converting:</p><ul><li>Creates a <strong>draft</strong> Expense with title, amount, tax amount, currency, and vendor copied from the purchase order, category <code>Other</code></li><li>Links the new expense back to the purchase order (visible in the expense&#39;s <strong>Related records</strong>)</li><li>Is <strong>one-way and one-time</strong> — once converted, the button disappears and the purchase order shows a link to the created expense instead</li></ul><p>If Expenses is not installed, the button does not appear; attempting the conversion via the API returns an error explaining that the Expenses module is required.</p><h2 id="what-s-not-here-yet" tabindex="-1">What&#39;s not here yet <a class="header-anchor" href="#what-s-not-here-yet" aria-label="Permalink to &quot;What&#39;s not here yet&quot;">​</a></h2><p>Purchase order PDFs/e-mail delivery and per-line partial receiving are planned but not part of this module yet — see the <a href="/getting-started/product-roadmap">Product Roadmap</a>.</p>',25)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
